package org.humanjourney.core.progress;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class ProgressGraphTest {
 static Path project(){return Path.of(System.getProperty("humanjourney.projectDir"));}
 static JsonObject example()throws Exception{return JsonParser.parseString(Files.readString(project().resolve("example-civilization-progress-datapack/data/human_journey/core/civilization_progress.json"))).getAsJsonObject();}
 static ProgressGraph parse(JsonObject o){return ProgressGraph.parse(o,id->!id.startsWith("missing:"));}
 static JsonObject node(JsonObject o,String suffix){for(var e:o.getAsJsonArray("nodes")){var n=e.getAsJsonObject();if(n.get("id").getAsString().equals("human_journey:"+suffix))return n;}throw new AssertionError(suffix);}
 static ProgressView.Node node(ProgressView view,String suffix){return view.nodes().stream().filter(n->n.id().equals("human_journey:"+suffix)).findFirst().orElseThrow();}
 static ProgressGraph.Ref score(String holder,int min,int max){return new ProgressGraph.Ref("score","hj_civ",holder,min,max);}
 static ProgressView view(ProgressGraph graph,Map<String,Integer> flags){return ProgressView.project(graph,(o,h)->OptionalInt.of(flags.getOrDefault(h,0)));}
 static JsonObject condition(String holder){var r=new JsonObject();r.addProperty("type","score");r.addProperty("objective","hj_civ");r.addProperty("holder",holder);r.addProperty("min",1);r.addProperty("max",1);return r;}
 @Test void exactExistingEra0ThreeBranchesConvergeAndEra1IsOnlyVisual()throws Exception{var graph=parse(example());assertEquals(18,graph.nodes().size());var cap=graph.nodeMap().get("human_journey:we_can_stay");assertEquals(Set.of("human_journey:rest_at_last","human_journey:carry_what_you_can","human_journey:new_continent"),new HashSet<>(cap.requires()));assertEquals(3,graph.connections().stream().filter(e->e.to().equals(cap.id())).count());assertEquals(ProgressGraph.EdgeKind.VISUAL,graph.connections().getLast().kind());assertTrue(graph.nodeMap().get("human_journey:era_1_placeholder").requires().isEmpty());}
 @Test void zeroOneTwoAndThreeEndpointsRequireAllWithoutAutoCompletingCapstone()throws Exception{var graph=parse(example());var flags=new HashMap<String,Integer>();assertEquals(ProgressView.State.LOCKED,node(view(graph,flags),"we_can_stay").state());for(String flag:List.of("#rest_at_last","#carry_what_you_can","#new_continent")){flags.put(flag,1);var v=view(graph,flags);assertEquals(flags.size()==3?ProgressView.State.AVAILABLE:ProgressView.State.LOCKED,node(v,"we_can_stay").state());assertEquals(ProgressView.State.LOCKED,node(v,"era_1_placeholder").state());}flags.put("#we_can_stay",1);var complete=view(graph,flags);assertEquals(ProgressView.State.COMPLETED,node(complete,"we_can_stay").state());assertEquals(ProgressView.State.LOCKED,node(complete,"era_1_placeholder").state());assertFalse(flags.containsKey("#era1"));assertFalse(flags.containsKey("#tech_agriculture"));}
 @Test void nothingCompletedShowsThreeIndependentStartingNodes()throws Exception{var view=view(parse(example()),Map.of());assertEquals(3,view.nodes().stream().filter(n->n.state()==ProgressView.State.AVAILABLE).count());assertEquals(0,view.nodes().stream().filter(n->n.state()==ProgressView.State.COMPLETED).count());}
 @Test void scoreCompletionIsAuthoritativeEvenWhenOtherGraphPrerequisitesAreIncomplete()throws Exception{var v=view(parse(example()),Map.of("#we_can_stay",1));assertEquals(ProgressView.State.COMPLETED,node(v,"we_can_stay").state());assertTrue(node(v,"we_can_stay").requires().stream().noneMatch(ProgressView.Requirement::completed));}
 @Test void allCategoriesArePresentationOnly()throws Exception{var o=example();node(o,"first_flame").addProperty("category","side");node(o,"first_wood").addProperty("category","discovery");var v=view(parse(o),Map.of());assertEquals(ProgressGraph.Category.SIDE,node(v,"first_flame").category());assertEquals(ProgressGraph.Category.DISCOVERY,node(v,"first_wood").category());}
 @Test void hiddenNodeNeverLeaksTitleDescriptionIdIconPositionOrIncidentEdges()throws Exception{var o=example();var n=node(o,"new_continent");n.addProperty("title","SECRET_TITLE");n.addProperty("description","SECRET_DESCRIPTION");var visible=new JsonArray();visible.add(condition("#reveal"));n.add("visible_when",visible);var v=view(parse(o),Map.of());String json=v.json();assertFalse(json.contains("SECRET"));assertFalse(json.contains("human_journey:new_continent"));assertTrue(node(v,"we_can_stay").requires().stream().anyMatch(r->!r.revealed()&&r.label().equals("Unrevealed prerequisite")));assertTrue(view(parse(o),Map.of("#reveal",1)).json().contains("SECRET_TITLE"));}
 @Test void hiddenEraMetadataDoesNotLeak()throws Exception{var o=example();var e=o.getAsJsonArray("eras").get(1).getAsJsonObject();e.addProperty("title","SECRET_ERA");var refs=new JsonArray();refs.add(condition("#reveal"));e.add("visible_when",refs);var v=view(parse(o),Map.of());assertEquals(1,v.eras().size());assertFalse(v.json().contains("SECRET_ERA"));assertFalse(v.json().contains("era_1_placeholder"));}
 @Test void visibilityRollbackRemovesPreviouslyRevealedContent()throws Exception{var o=example();var a=new JsonArray();a.add(condition("#reveal"));node(o,"new_continent").add("visible_when",a);var g=parse(o);assertTrue(view(g,Map.of("#reveal",1)).nodes().size()>view(g,Map.of()).nodes().size());}
 @Test void unknownScoreIsLockedAndNeverCreated()throws Exception{var calls=new ArrayList<String>();var view=ProgressView.project(parse(example()),(o,h)->{calls.add(h);return OptionalInt.empty();});assertTrue(view.nodes().stream().filter(n->!n.placeholder()).noneMatch(ProgressView.Node::known));assertTrue(view.nodes().stream().allMatch(n->n.state()==ProgressView.State.LOCKED));assertEquals(new HashSet<>(calls).size(),calls.size());}
 @Test void sharedScoreRangeIsInclusiveAndBinaryFlagIsNotGeneralEraIndex(){var r=score("#era1",1,1);assertFalse(r.test((o,h)->OptionalInt.of(0)));assertTrue(r.test((o,h)->OptionalInt.of(1)));assertFalse(r.test((o,h)->OptionalInt.of(2)));assertFalse(r.test((o,h)->OptionalInt.empty()));}
 @Test void unsupportedSchemaAndReferenceTypesReject()throws Exception{var o=example();o.addProperty("schema_version",2);assertThrows(IllegalArgumentException.class,()->parse(o));o.addProperty("schema_version",1);node(o,"first_flame").getAsJsonObject("completion").addProperty("type","advancement");assertThrows(IllegalArgumentException.class,()->parse(o));}
 @Test void selectorOrPlayerReferencesCannotBeAuthored()throws Exception{for(String holder:List.of("@a","PlayerName","","#bad selector")){var o=example();node(o,"first_flame").getAsJsonObject("completion").addProperty("holder",holder);assertThrows(IllegalArgumentException.class,()->parse(o));}}
 @Test void unknownEraNodeItemAndConnectionReject()throws Exception{var a=example();node(a,"first_flame").addProperty("era","unknown");assertThrows(IllegalArgumentException.class,()->parse(a));var b=example();node(b,"first_flame").addProperty("icon","missing:icon");assertThrows(IllegalArgumentException.class,()->parse(b));var c=example();c.getAsJsonArray("connections").get(0).getAsJsonObject().addProperty("from","missing");assertThrows(IllegalArgumentException.class,()->parse(c));}
 @Test void duplicateIdsAndMissingPrerequisiteReject()throws Exception{var a=example();a.getAsJsonArray("nodes").add(a.getAsJsonArray("nodes").get(0).deepCopy());assertThrows(IllegalArgumentException.class,()->parse(a));var b=example();node(b,"we_can_stay").getAsJsonArray("requires").add("missing");assertThrows(IllegalArgumentException.class,()->parse(b));}
 @Test void prerequisiteEdgeMustBeExplicitlyDeclaredAndCannotBeInferredFromGeometry()throws Exception{var a=example();var edge=a.getAsJsonArray("connections").get(a.getAsJsonArray("connections").size()-1).getAsJsonObject();edge.addProperty("kind","prerequisite");assertThrows(IllegalArgumentException.class,()->parse(a));var b=example();b.getAsJsonArray("connections").remove(0);assertThrows(IllegalArgumentException.class,()->parse(b));}
 @Test void requiredAndVisualCyclesReject()throws Exception{var o=example();var edge=new JsonObject();edge.addProperty("from","human_journey:we_can_stay");edge.addProperty("to","human_journey:first_flame");edge.addProperty("kind","visual");o.getAsJsonArray("connections").add(edge);assertThrows(IllegalArgumentException.class,()->parse(o));}
 @Test void orLogicAndUnknownFieldsAreNotSilentlyAccepted()throws Exception{var o=example();node(o,"we_can_stay").add("requires_any",new JsonArray());assertThrows(IllegalArgumentException.class,()->parse(o));}
 @Test void malformedNumbersAndInvalidPlaceholdersReject()throws Exception{var o=example();node(o,"first_flame").addProperty("x","NaN");assertThrows(IllegalArgumentException.class,()->parse(o));var b=example();node(b,"era_1_placeholder").remove("available_when");assertThrows(IllegalArgumentException.class,()->parse(b));}
 @Test void deterministicReloadPreservesLayoutAndDoesNotWriteAnyFlag()throws Exception{var a=parse(example());var b=parse(example());assertEquals(a,b);assertEquals(view(a,Map.of()).json(),view(b,Map.of()).json());}
 @Test void frozenProductionReferenceMatchesEveryEra0ScoreTitleAndDescription()throws Exception{var source=JsonParser.parseString(Files.readString(project().resolve("src/test/resources/progress/era0-reference.json"))).getAsJsonObject();assertEquals("0.5.17",source.get("datapack_version").getAsString());var files=source.getAsJsonObject("files");String sync=files.get("human_journey/source/data/human_journey/function/sync.mcfunction").getAsString();var graph=parse(example());for(var n:graph.nodes()){if(n.placeholder())continue;assertEquals("hj_civ",n.completion().objective());assertTrue(sync.contains("execute if score "+n.completion().holder()+" hj_civ matches 1 run advancement grant"));assertTrue(files.entrySet().stream().filter(e->e.getKey().contains("/advancement/era0/")).map(e->e.getValue().getAsString()).anyMatch(t->t.contains(n.title())&&t.contains(n.description())));}assertTrue(graph.references().stream().noneMatch(r->r.holder().equals("#era1")||r.holder().equals("#tech_agriculture")));}
}
